## Técnicas de optimización

### 1. Memoización

```javascript
function memoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

const fibMemo = memoize(function fib(n) {
  if (n <= 1) return n;
  return fibMemo(n - 1) + fibMemo(n - 2);
});
```

### 2. Debounce

```javascript
function debounce(fn, ms) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), ms);
  };
}

// Solo ejecuta 300ms después del último keystroke:
const buscar = debounce(query => fetchResultados(query), 300);
inputBusqueda.addEventListener('input', e => buscar(e.target.value));
```

### 3. Throttle

```javascript
function throttle(fn, ms) {
  let ultima = 0;
  return function(...args) {
    const ahora = Date.now();
    if (ahora - ultima >= ms) {
      ultima = ahora;
      return fn.apply(this, args);
    }
  };
}

// Máximo una vez cada 100ms durante scroll:
window.addEventListener('scroll', throttle(() => actualizarUI(), 100));
```

