// Profiler simple para comparar implementaciones
function profiler(nombre, fn, iteraciones = 1000) {
  // Warm-up (evita JIT artifacts):
  fn();
  fn();

  const inicio = performance.now();
  for (let i = 0; i < iteraciones; i++) {
    fn();
  }
  const fin = performance.now();

  const total = fin - inicio;
  const porIteracion = total / iteraciones;

  return {
    nombre,
    total: total.toFixed(3),
    promedio: porIteracion.toFixed(6),
    ops: Math.round(1000 / porIteracion),
  };
}

// Comparar dos implementaciones:
const datos = Array.from({ length: 1000 }, (_, i) => i);

const r1 = profiler('for loop', () => {
  let sum = 0;
  for (let i = 0; i < datos.length; i++) sum += datos[i];
  return sum;
});

const r2 = profiler('reduce', () => {
  return datos.reduce((a, b) => a + b, 0);
});

console.log(r1);
console.log(r2);
console.log(`${r1.nombre} es ~${(r2.ops / r1.ops).toFixed(1)}x más lento que ${r2.nombre}`);

// Debounce y throttle combinados — comparar comportamiento
function crearContadorLlamadas(fn) {
  let llamadas = 0;
  return {
    fn: (...args) => { llamadas++; return fn(...args); },
    reset: () => { llamadas = 0; },
    getLlamadas: () => llamadas,
  };
}

function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

function throttle(fn, ms) {
  let ultima = 0;
  return (...args) => {
    const ahora = Date.now();
    if (ahora - ultima >= ms) { ultima = ahora; return fn(...args); }
  };
}

const contador = crearContadorLlamadas(x => x * 2);
const debouncedFn = debounce(contador.fn, 50);

// Simular 10 llamadas rápidas:
for (let i = 0; i < 10; i++) debouncedFn(i);

await new Promise(r => setTimeout(r, 100));

console.log('Debounce: llamadas reales ejecutadas:', contador.getLlamadas()); // 1

