function medirTiempo(fn, iteraciones = 1) {
  const inicio = performance.now();
  for (let i = 0; i < iteraciones; i++) fn();
  const fin = performance.now();

  const total = (fin - inicio);
  const promedio = total / iteraciones;

  return {
    total: total.toFixed(3),
    promedio: promedio.toFixed(6),
    operacionesPorSegundo: Math.round(1000 / promedio),
  };
}

const datos = Array.from({ length: 100 }, (_, i) => i + 1);

const r1 = medirTiempo(() => {
  let s = 0; for (const n of datos) s += n; return s;
}, 1000);

const r2 = medirTiempo(() => {
  return datos.reduce((a, b) => a + b, 0);
}, 1000);

const tieneTiempoTotal = typeof parseFloat(r1.total) === 'number' && parseFloat(r1.total) >= 0;
const tieneOps = r1.operacionesPorSegundo > 0;
const tienePromedio = parseFloat(r1.promedio) >= 0;

console.log('For loop:', r1);
console.log('Reduce:', r2);

function debounce(fn, ms) {
  let timer;
  return function(...args) {
