function crearBenchmark() {
  const funciones = new Map();

  return {
    agregar(nombre, fn) {
      funciones.set(nombre, fn);
    },
    ejecutar(iteraciones = 1000) {
      const resultados = [];

      for (const [nombre, fn] of funciones) {
        // Warm-up
        fn(); fn();

        const inicio = performance.now();
        for (let i = 0; i < iteraciones; i++) fn();
        const fin = performance.now();

        const ms = (fin - inicio) / iteraciones;
        const ops = Math.round(1000 / ms);
        resultados.push({ nombre, ops, ms: parseFloat(ms.toFixed(6)) });
      }

      // Ordenar por ops descendente (más rápido primero)
      resultados.sort((a, b) => b.ops - a.ops);

      // Agregar ratio relativo
      const maxOps = resultados[0].ops;
      resultados.forEach(r => {
        r.relativo = parseFloat((maxOps / r.ops).toFixed(2));
      });

      return resultados;
    },
  };
}

const bench = crearBenchmark();

bench.agregar('Array.from range', () => Array.from({ length: 100 }, (_, i) => i));
bench.agregar('Array fill + map', () => new Array(100).fill(0).map((_, i) => i));
bench.agregar('for loop push', () => { const a = []; for (let i = 0; i < 100; i++) a.push(i); return a; });

const resultados = bench.ejecutar(500);

const tieneRelativo = resultados[0].relativo === 1;
const estaOrdenado = resultados[0].ops >= resultados[1].ops;
const tiene3Resultados = resultados.length === 3;

console.log('\nResultados:');
resultados.forEach(r => {
  console.log(`${r.nombre}: ${r.ops} ops/s (${r.relativo}x)`);
});
